add_filter( 'woocommerce_localisation_address_formats', 'perfectpixel_country_address_format' );

function perfectpixel_country_address_format( $formats ) {
	$country = strtoupper( sanitize_text_field( '{{address_format_country}}' ) );
	if ( $country ) {
		$formats[ $country ] = str_replace( '|', "\n", '{{address_format_template}}' );
	}
	return $formats;
}
